    /// <inheritdoc cref="Quaternion.CreateFromRotationMatrix(Matrix4x4)" />
    public static doubleQuat CreateFromRotationMatrix(double4x4 matrix)
    {
        var trace = matrix.M11 + matrix.M22 + matrix.M33;

        doubleQuat q = default;

        if (trace > 0.0)
        {
            var s = double.Sqrt(trace + 1);
            q.W = s * 0.5;
            s = 0.5 / s;
            q.X = (matrix.M23 - matrix.M32) * s;
            q.Y = (matrix.M31 - matrix.M13) * s;
            q.Z = (matrix.M12 - matrix.M21) * s;
