    /// <inheritdoc cref="Quaternion.CreateFromYawPitchRoll(float, float, float)" />
    public static doubleQuat CreateFromYawPitchRoll(double yaw, double pitch, double roll)
    {
        //  Roll first, about axis the object is facing, then
        //  pitch upward, then yaw to face into the new heading
        var (sr, cr) = double.SinCos(roll * 0.5);
        var (sp, cp) = double.SinCos(pitch * 0.5);
        var (sy, cy) = double.SinCos(yaw * 0.5);

        doubleQuat result;

        result.X = cy * sp * cr + sy * cp * sr;
        result.Y = sy * cp * cr - cy * sp * sr;
        result.Z = cy * cp * sr - sy * sp * cr;
        result.W = cy * cp * cr + sy * sp * sr;

        return result;
    }

