        var t1 = 1 - t;

        var dot = Dot(a, b);

        var r = dot >= 0
            ? a * t1 + b * t
            : a * t1 - b * t;

        // Normalize it.
        var invNorm = 1 / double.Sqrt(r.LengthSquared());
        return r * invNorm;
    }

    private const double SlerpEpsilon = 1e-12;

    /// <inheritdoc cref="Quaternion.Slerp(Quaternion, Quaternion, float)" />
    public static doubleQuat Slerp(doubleQuat a, doubleQuat b, double amount)
    {
        var t = amount;

        var cosOmega = Dot(a, b);

        var flip = false;

        if (cosOmega < 0)
        {
            flip = true;
            cosOmega = -cosOmega;
        }

        double s1,
            s2;

        if (cosOmega > 1 - SlerpEpsilon)
        {
            // Too close, do straight linear interpolation.
            s1 = 1 - t;
            s2 = flip ? -t : t;
        }
        else
        {
            var omega = double.Acos(cosOmega);
            var invSinOmega = 1 / double.Sin(omega);

            s1 = double.Sin((1 - t) * omega) * invSinOmega;
            s2 = flip ? -double.Sin(t * omega) * invSinOmega : double.Sin(t * omega) * invSinOmega;
        }

        return a * s1 + b * s2;
    }

